<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('ai.use');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$planAi=\App\Core\Tenant::aiEnabled((int)$user['tenant_id']);$mode=$_GET['mode']??$_POST['mode']??'soap';if(!in_array($mode,['soap','rag','audit','longitudinal'],true))$mode='soap';$docId=(int)($_GET['document_id']??0);$selected=(int)($_POST['patient_id']??0);$st=db()->prepare("SELECT * FROM patients WHERE tenant_id=:t AND primary_professional_id=:u AND status='active' ORDER BY name");$st->execute(['t'=>$user['tenant_id'],'u'=>$user['id']]);$patients=$st->fetchAll();$prompt='';if($docId&&$mode==='audit'){$st=db()->prepare("SELECT d.content_enc,d.title,p.name patient_name FROM clinical_documents d JOIN patients p ON p.id=d.patient_id AND p.tenant_id=d.tenant_id WHERE d.id=:id AND d.tenant_id=:t AND d.professional_id=:u");$st->execute(['id'=>$docId,'t'=>$user['tenant_id'],'u'=>$user['id']]);if($d=$st->fetch()){$c=\App\Core\Crypto::decrypt($d['content_enc'],true);$prompt="Audite a estrutura formal deste documento intitulado '{$d['title']}'. Aponte campos ausentes, linguagem que exige revisão e itens que precisam conferência humana.\n\n".implode("\n\n",array_map(fn($k,$v)=>strtoupper($k).": ".$v,array_keys($c),array_values($c)));$selected=0;}}$result=null;$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&$planAi){verify_csrf();$aiLimit=\App\Core\RateLimiter::hit('ai:'.$user['tenant_id'].':'.$user['id'],(int)env('RATE_LIMIT_AI_ATTEMPTS',60),(int)env('RATE_LIMIT_AI_WINDOW',3600));if(!$aiLimit['allowed']){$error='Limite temporário de solicitações à IA atingido. Tente novamente mais tarde.';} $prompt=trim($_POST['prompt']??'');$selected=(int)($_POST['patient_id']??0);$known=[];$patient=null;if($selected){foreach($patients as $x)if((int)$x['id']===$selected)$patient=$x;if(!$patient)$error='Paciente não autorizado.';else{$known=array_filter([$patient['name'],$patient['preferred_name']??null]);if($mode==='longitudinal'){$st=db()->prepare("SELECT content_enc,created_at FROM clinical_records WHERE tenant_id=:t AND patient_id=:p AND created_at>=DATE_SUB(NOW(),INTERVAL 6 MONTH) ORDER BY created_at");$st->execute(['t'=>$user['tenant_id'],'p'=>$selected]);$history=[];foreach($st->fetchAll() as $r){$c=\App\Core\Crypto::decrypt($r['content_enc'],true);$history[]=date('Y-m-d',strtotime($r['created_at'])).' '.implode(' | ',array_map('strval',$c));}$prompt.="\n\nHISTÓRICO PARA ANÁLISE LONGITUDINAL:\n".implode("\n",$history);}}}if(!$error&&$prompt==='')$error='Digite uma solicitação.';if(!$error){$svc=new \App\Core\AiService();$result=$svc->ask($prompt,$mode,$known,(int)$user['tenant_id']);if($result['ok']??false){$st=db()->prepare("INSERT INTO ai_interactions(tenant_id,user_id,patient_id,mode,prompt_hash,response_enc,sources_json,created_at)VALUES(:t,:u,:p,:m,:h,:r,:s,NOW())");$st->execute(['t'=>$user['tenant_id'],'u'=>$user['id'],'p'=>$selected?:null,'m'=>$mode,'h'=>hash('sha256',$result['sanitized_prompt']??$prompt),'r'=>\App\Core\Crypto::encrypt($result['text']),'s'=>json_encode(array_map(fn($x)=>['id'=>$x['id']??null,'title'=>$x['title']??'','source_url'=>$x['source_url']??null],$result['sources']??[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);audit('ai.request','ai_interaction',(int)db()->lastInsertId(),['mode'=>$mode,'patient_id'=>$selected?:null]);}else $error=$result['error']??'Falha na IA.';}}
layout('Copiloto IA',function()use($mode,$patients,$selected,$prompt,$result,$error,$planAi){?><div class="page-head"><div><span class="eyebrow">IA assistiva</span><h1>Copiloto clínico</h1><p>Anonimização local + base interna + resposta para revisão profissional.</p></div></div><?php if(!$planAi):?><div class="error-box" style="margin-bottom:18px">O plano atual não inclui Copiloto IA. O gestor pode consultar os planos na área de assinatura.</div><?php endif?><div class="grid-2"><form method="post" class="card form-grid ai-widget"><?=csrf_field()?><div class="ai-glow"></div><div class="field"><label>Modo</label><select name="mode"><option value="soap" <?=$mode==='soap'?'selected':''?>>Estruturar SOAP</option><option value="rag" <?=$mode==='rag'?'selected':''?>>Pesquisa RAG</option><option value="audit" <?=$mode==='audit'?'selected':''?>>Auditoria de documento</option><option value="longitudinal" <?=$mode==='longitudinal'?'selected':''?>>Análise longitudinal</option></select></div><div class="field"><label>Paciente (opcional; exigido para histórico longitudinal)</label><select name="patient_id"><option value="">Sem paciente</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>" <?=$selected===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach?></select></div><div class="field"><label>Solicitação / notas brutas</label><textarea name="prompt" style="min-height:280px" placeholder="Ex.: Estruture estas notas em SOAP..."><?=e($prompt)?></textarea></div><div class="help">Nunca aceite a saída como diagnóstico ou documento final sem revisão. O filtro local mascara identificadores conhecidos antes do envio externo.</div><button class="button" <?=!$planAi?'disabled':''?>>Processar com IA</button></form><section class="card"><h2>Resposta</h2><?php if($error):?><div class="error-box"><?=e($error)?></div><?php elseif($result&&($result['ok']??false)):?><div class="record" style="line-height:1.75;white-space:pre-wrap"><?=e($result['text'])?></div><h3>Fontes recuperadas</h3><?php if(!($result['sources']??[])):?><p class="muted">Nenhuma fonte interna foi recuperada. Em modo RAG, trate a resposta como insuficientemente fundamentada.</p><?php endif?><?php foreach($result['sources']??[] as $s):?><div class="record"><strong><?=e($s['title'])?></strong><?php if($s['source_url']):?><br><a href="<?=e($s['source_url'])?>" target="_blank" rel="noopener">Origem</a><?php endif?></div><?php endforeach?><?php else:?><p class="muted">A resposta aparecerá aqui. Configure o provedor no <code>.env</code> para habilitar chamadas externas.</p><?php endif?></section></div><?php },['active'=>'ai']);
